        System.out.println("Extracted jar valid, entries: " + springJar.size());
        JarEntry springAppEntry = springJar.getJarEntry("org/springframework/boot/SpringApplication.class");
        System.out.println("SpringApplication entry: " + springAppEntry);
        springJar.close();
        outer.close();
    }
}
