import java.io.*;
import java.net.*;
import java.util.*;
import java.util.jar.*;

public class DebugLauncher {
    public static void main(String[] args) throws Exception {
        // Simulate what JarFileArchive does
        File jarFile = new File("/workspace/target/keyguard-platform-1.0.0.jar");
        JarFile jf = new JarFile(jarFile);

        // Collect all BOOT-INF/lib/ jars as URLs
        List<URL> urls = new ArrayList<>();
        Enumeration<JarEntry> entries = jf.entries();
        while (entries.hasMoreElements()) {
            JarEntry entry = entries.nextElement();
            String name = entry.getName();
            if (name.startsWith("BOOT-INF/lib/") && !entry.isDirectory()) {
                // Create URL like Spring Boot loader does
                URL url = new URL("jar", "", -1, "file:" + jarFile.getAbsolutePath() + "!/" + name);
                urls.add(url);
            }
        }

        // Add BOOT-INF/classes/ too
        URL classesUrl = new URL("file:" + jarFile.getAbsolutePath() + "!/BOOT-INF/classes/");
        urls.add(classesUrl);

        System.out.println("Total URLs: " + urls.size());

        // Create URLClassLoader with these URLs
        URLClassLoader cl = new URLClassLoader(urls.toArray(new URL[0]), null);

        // Try to load SpringApplication
        try {
            Class<?> sa = cl.loadClass("org.springframework.boot.SpringApplication");
            System.out.println("LOADED: " + sa.getName());
        } catch (ClassNotFoundException e) {
            System.out.println("FAILED: " + e.getMessage());
            // Try to find the resource
            URL res = cl.findResource("org/springframework/boot/SpringApplication.class");
            System.out.println("Resource: " + res);
        }

        // Try another class
        try {
            Class<?> keyGuard = cl.loadClass("com.keyguard.platform.KeyGuardApplication");
            System.out.println("LOADED KeyGuard: " + keyGuard.getName());
        } catch (Exception e) {
            System.out.println("FAILED KeyGuard: " + e.getMessage());
        }

        jf.close();
        cl.close();
    }
}
