import java.io.*;
import java.net.*;
import java.util.*;
import java.util.jar.*;

public class DebugLauncher2 {
    public static void main(String[] args) throws Exception {
        // Register the Spring Boot custom handlers
        // This is what Handlers.register() does
        String pkgs = System.getProperty("java.protocol.handler.pkgs", "");
        if (!pkgs.contains("org.springframework.boot.loader")) {
            if (pkgs.isEmpty()) {
                System.setProperty("java.protocol.handler.pkgs", "org.springframework.boot.loader.net.protocol");
            } else {
                System.setProperty("java.protocol.handler.pkgs", pkgs + "|org.springframework.boot.loader.net.protocol");
            }
        }

        File jarFile = new File("/workspace/target/keyguard-platform-1.0.0.jar");
        JarFile jf = new JarFile(jarFile);

        // Now test the nested jar URL using Spring Boot's JarUrl
        // We need the loader classes on the classpath
        List<URL> urls = new ArrayList<>();

        // First, add the loader classes and outer jar to enable nested URL resolution
        urls.add(jarFile.toURI().toURL());

        Enumeration<JarEntry> entries = jf.entries();
        while (entries.hasMoreElements()) {
            JarEntry entry = entries.nextElement();
            String name = entry.getName();
            if (name.startsWith("BOOT-INF/lib/spring-boot-3") && !entry.isDirectory()) {
                // Use Spring Boot's JarUrl to create the nested URL
                URL nestedUrl = org.springframework.boot.loader.net.protocol.jar.JarUrl.create(jarFile, entry);
                System.out.println("Nested URL for " + name + ": " + nestedUrl);
                System.out.println("  Protocol: " + nestedUrl.getProtocol());

                // Try to open connection and verify it works
                try {
                    URLConnection conn = nestedUrl.openConnection();
                    System.out.println("  Connection type: " + conn.getClass().getName());
                    if (conn instanceof JarURLConnection) {
                        JarFile nestedJar = ((JarURLConnection) conn).getJarFile();
                        System.out.println("  Nested jar valid: entries=" + nestedJar.size());
                        JarEntry springEntry = nestedJar.getJarEntry("org/springframework/boot/SpringApplication.class");
                        System.out.println("  SpringApplication found: " + (springEntry != null));
                    }
                } catch (Exception e) {
                    System.out.println("  ERROR: " + e.getMessage());
                    e.printStackTrace(System.out);
                }
            }
        }

        jf.close();
    }
}
